contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address impl, address settings, bytes calldata params, address ownedBy) public payable {
        require(impl != address(0));
        require(settings != address(0));
        c.initialize();
        address ownerBefore = c.owner();
        c.updateAlloSettings(settings);
        c.updateRoundImplementation(payable(impl));
        address storedImpl = c.roundImplementation();
        address storedSettings = c.alloSettings();
        // this contract is the owner but has never been registered as a program
        // operator (no registration path is exposed), so create() must revert
        // for every input and must not disturb the stored configuration
        bool createReverted;
        try c.create(params, ownedBy) { createReverted = false; } catch { createReverted = true; }
        address storedImplAfter = c.roundImplementation();
        address storedSettingsAfter = c.alloSettings();
        assert(
            ownerBefore == address(this) &&
            storedImpl == impl &&
            storedSettings == settings &&
            createReverted &&
            storedImplAfter == impl &&
            storedSettingsAfter == settings
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newSettings) public payable {
        // The deployer of c is this contract, so it is the owner; no precondition
        // is needed on the parameters: any address (even zero) must be accepted.
        bool updateReverted;
        try c.updateAlloSettings(newSettings) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }
        address stored = c.alloSettings();
        address ownerNow = c.owner();
        // Owner-only update must succeed for ANY input (including address(0),
        // unlike updateRoundImplementation) and store the value exactly.
        assert(
            ownerNow == address(this) &&
            !updateReverted &&
            stored == newSettings
        );
    }
    receive() external payable {}
}

