contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newImpl) public payable {
        c.initialize();
        address beforeImpl = c.roundImplementation();
        bool reverted;
        if (newImpl == address(0)) {
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            c.updateRoundImplementation(payable(newImpl));
            reverted = false;
        }
        address afterImpl = c.roundImplementation();
        if (newImpl == address(0)) {
            assert(reverted && afterImpl == beforeImpl);
        } else {
            assert(!reverted && afterImpl == newImpl);
        }
    }
    receive() external payable {}
}

